public final class ArmorAudit {
 private static void check(String name,boolean ok,Object info){ServerAudit.check("armor: "+name,ok,info);}
 private static ItemStack charged(String name,double eu){var s=new ItemStack(EMTItems.ARMOR.get(name).get());ElectricItem.manager.charge(s,eu,10,true,false);return s;}
 private static void clear(Player p){for(var slot:new EquipmentSlot[]{EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET})p.setItemSlot(slot,ItemStack.EMPTY);p.getInventory().clearContent();p.removeAllEffects();p.setAbsorptionAmount(0);p.setShiftKeyDown(false);Keyboard.processKeyUpdate(p,0);}
 private static void tick(Player p,ItemStack s){((ic2.core.item.armor.ItemArmorIC2)s.getItem()).onArmorTick(p.level(),p,s);}
 public static void run(ServerLevel l,BlockPos anchor){var p=new net.minecraft.server.level.ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"EMTArmorAudit"),net.minecraft.server.level.ClientInformation.createDefault());p.connection=FakePlayerFactory.getMinecraft(l).connection;p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;try{var spawn=net.minecraft.server.level.ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");spawn.setAccessible(true);spawn.setInt(p,0);}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}clear(p);p.setPos(anchor.getX()+64.5,anchor.getY()+3,anchor.getZ()+20.5);
  int i=0;double[] caps={10000,100000,10000000,10000000,100000,1000000,10000000,100000,1000000};for(var kind:EMTArmor.Kind.values()){var s=charged(kind.name().toLowerCase(Locale.ROOT),2000);var a=(EMTArmor)s.getItem();check(kind+" original capacity",a.getMaxCharge(s)==caps[i++],a.getMaxCharge(s));if(a.goggles())check(kind+" real revealing interfaces",a.showNodes(s,p)&&a.showIngamePopups(s,p),a.discount);}
  var nano=charged("nano_goggles",0);p.setItemSlot(EquipmentSlot.HEAD,nano);tick(p,nano);check("reference nano night vision costs zero EU",p.hasEffect(MobEffects.NIGHT_VISION)&&ElectricItem.manager.getCharge(nano)==0,"night vision");boolean nv=EMTConfig.NIGHTVISION_OFF.get();try{EMTConfig.NIGHTVISION_OFF.set(true);p.removeEffect(MobEffects.NIGHT_VISION);tick(p,nano);check("night vision disabling config",!p.hasEffect(MobEffects.NIGHT_VISION),"disabled");}finally{EMTConfig.NIGHTVISION_OFF.set(nv);}
  clear(p);var quantum=charged("quantum_goggles",50000);p.setItemSlot(EquipmentSlot.HEAD,quantum);p.setAirSupply(80);tick(p,quantum);check("quantum goggles refill200air for1000EU",p.getAirSupply()==280&&ElectricItem.manager.getCharge(quantum)==49000,p.getAirSupply());p.setAirSupply(300);p.addEffect(new MobEffectInstance(MobEffects.POISON,200,1));p.addEffect(new MobEffectInstance(MobEffects.REGENERATION,200,0));tick(p,quantum);check("quantum goggles use reference amplified milk cure",!p.hasEffect(MobEffects.POISON)&&!p.hasEffect(MobEffects.REGENERATION)&&ElectricItem.manager.getCharge(quantum)==29000,ElectricItem.manager.getCharge(quantum));p.removeAllEffects();p.addEffect(new MobEffectInstance(MobEffects.WITHER,200,0));tick(p,quantum);check("quantum wither cure costs15000EU",!p.hasEffect(MobEffects.WITHER)&&ElectricItem.manager.getCharge(quantum)==14000,ElectricItem.manager.getCharge(quantum));p.removeAllEffects();p.addEffect(new MobEffectInstance(MobEffects.CONFUSION,200,0));tick(p,quantum);check("quantum nausea cure costs5000EU",!p.hasEffect(MobEffects.CONFUSION)&&ElectricItem.manager.getCharge(quantum)==9000,ElectricItem.manager.getCharge(quantum));
  clear(p);var solar=charged("solar_goggles",0);p.setItemSlot(EquipmentSlot.HEAD,solar);tick(p,solar);check("solar goggles reference generation is256EU clear day",ElectricItem.manager.getCharge(solar)==256,ElectricItem.manager.getCharge(solar));var boots=charged("electric_boots_traveller",99999.5);p.setItemSlot(EquipmentSlot.FEET,boots);double before=ElectricItem.manager.getCharge(solar);tick(p,solar);check("solar goggles prioritize armor with fractional EU conserved",ElectricItem.manager.getCharge(boots)==100000&&ElectricItem.manager.getCharge(solar)==before+255.5,ElectricItem.manager.getCharge(solar)-before);
  p.setItemSlot(EquipmentSlot.FEET,charged("quantum_boots_traveller",1));p.setItemSlot(EquipmentSlot.CHEST,charged("nano_wings",1));check("real Thaumcraft vis discount includes mixed EMT equipment",Math.abs(VisGearDiscount.armor(p,Aspect.AIR)-.17f)<.000001,VisGearDiscount.armor(p,Aspect.AIR));
  clear(p);for(String name:List.of("electric_boots_traveller","nano_boots_traveller","quantum_boots_traveller")){var s=charged(name,5000);var a=(EMTArmor)s.getItem();p.setItemSlot(EquipmentSlot.FEET,s);p.setDeltaMovement(0,.42,0);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new LivingEvent.LivingJumpEvent(p));check(name+" actual jump event adds original bonus",Math.abs(p.getDeltaMovement().y-(.42+a.jumpBonus()))<.000001,p.getDeltaMovement().y);var fall=new LivingFallEvent(p,20,1);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(fall);check(name+" cancels fall for flat EU payment",fall.isCanceled()&&ElectricItem.manager.getCharge(s)==5000-a.perDamage,ElectricItem.manager.getCharge(s));}
  var activeBoots=p.getItemBySlot(EquipmentSlot.FEET);Keyboard.processKeyUpdate(p,(1<<Keyboard.Key.boost.ordinal())|(1<<Keyboard.Key.modeSwitch.ordinal()));tick(p,activeBoots);check("boots boost toggle stored per stack",EMTArmor.tag(activeBoots).getBoolean("speedBoostActive"),EMTArmor.tag(activeBoots));for(int n=0;n<4;n++)tick(p,activeBoots);check("held boost keys are debounced",EMTArmor.tag(activeBoots).getBoolean("speedBoostActive"),"still enabled");Keyboard.processKeyUpdate(p,1<<Keyboard.Key.forward.ordinal());net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new PlayerTickEvent.Pre(p));check("traveller step height reaches one block",p.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT)>=1,"step");p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new PlayerTickEvent.Pre(p));check("unequipping boots restores step modifier",!p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT).hasModifier(ArmorEvents.STEP),"restored");
  clear(p);int kind=0;for(String name:List.of("feather_wings","thaumium_wings","nano_wings","quantum_wings")){var s=charged(name,1000);p.setItemSlot(EquipmentSlot.CHEST,s);p.setOnGround(false);p.setDeltaMovement(.2,-.4,.2);Keyboard.processKeyUpdate(p,1<<Keyboard.Key.jump.ordinal());for(int n=0;n<7;n++)tick(p,s);p.setDeltaMovement(.2,-.4,.2);before=ElectricItem.manager.getCharge(s);Keyboard.processKeyUpdate(p,0);tick(p,s);double expectedY=new double[]{.77,1.05,1.75,2.31}[kind],cost=kind<2?0:kind==2?87.5:161.7;check(name+" release flap follows original force",Math.abs(p.getDeltaMovement().y-expectedY)<.00001,p.getDeltaMovement().y);check(name+" flap EU budget",Math.abs(ElectricItem.manager.getCharge(s)-(before-cost))<.0001,ElectricItem.manager.getCharge(s));p.setHealth(20);p.invulnerableTime=0;p.removeAllEffects();p.hurt(p.damageSources().fall(),4);check(name+" original fall damage multiplier",Math.abs(p.getHealth()-(20-4*WingLogic.FALL[kind]))<.001,p.getHealth());kind++;}
  clear(p);var empty=charged("nano_wings",0);p.setItemSlot(EquipmentSlot.CHEST,empty);p.setDeltaMovement(0,-.4,0);Keyboard.processKeyUpdate(p,1<<Keyboard.Key.jump.ordinal());for(int n=0;n<7;n++)tick(p,empty);Keyboard.processKeyUpdate(p,0);tick(p,empty);check("empty electric wings cannot flap for free",p.getDeltaMovement().y==-.4&&ElectricItem.manager.getCharge(empty)==0,p.getDeltaMovement().y);
  clear(p);var chest=charged("infused_quantum_chestplate",10000);p.setItemSlot(EquipmentSlot.CHEST,chest);int type=0;for(var item:List.of(Ic2Items.ELECTRIC_JETPACK.get(),EMTItems.ARMOR.get("thaumium_wings").get(),EMTItems.ARMOR.get("nano_wings").get(),EMTItems.ARMOR.get("quantum_wings").get())){type++;var attachment=new ItemStack(item);ElectricItem.manager.charge(attachment,777.5,10,true,false);attachment.set(DataComponents.CUSTOM_NAME,Component.literal("attachment audit"));if(type==2)attachment.setDamageValue(17);p.setShiftKeyDown(true);p.setItemInHand(InteractionHand.MAIN_HAND,attachment);check("attach module "+type,ItemInfusedChestplate.attach(p,chest)&&ItemInfusedChestplate.attachment(chest)==type&&p.getMainHandItem().isEmpty(),ItemInfusedChestplate.attachment(chest));check("attachment cooldown prevents immediate detach "+type,!ItemInfusedChestplate.detach(p,chest),"cooldown");for(int n=0;n<30;n++)tick(p,chest);check("detach module returns original components "+type,ItemInfusedChestplate.detach(p,chest)&&p.getMainHandItem().is(item)&&p.getMainHandItem().has(DataComponents.CUSTOM_NAME)&&(type==2?p.getMainHandItem().getDamageValue()==17:ElectricItem.manager.getCharge(p.getMainHandItem())==777.5),p.getMainHandItem());check("detachment cannot duplicate module "+type,!ItemInfusedChestplate.detach(p,chest)&&ItemInfusedChestplate.attachment(chest)==0,"once");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);for(int n=0;n<30;n++)tick(p,chest);}
  p.setShiftKeyDown(false);var data=EMTArmor.tag(chest);data.putBoolean("hoverMode",true);EMTArmor.save(chest,data);p.setDeltaMovement(0,-.1,0);before=ElectricItem.manager.getCharge(chest);tick(p,chest);check("hover cannot fly without an attached jetpack",p.getDeltaMovement().y==-.1&&ElectricItem.manager.getCharge(chest)==before,"no module");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Ic2Items.ELECTRIC_JETPACK.get()));ItemInfusedChestplate.attach(p,chest);p.setDeltaMovement(Vec3.ZERO);before=ElectricItem.manager.getCharge(chest);((ItemInfusedChestplate)chest.getItem()).jetpack(p,chest,false);check("attached jetpack uses chest EU and original thrust",p.getDeltaMovement().y>0&&ElectricItem.manager.getCharge(chest)==before-8,p.getDeltaMovement().y);
  clear(p);var electric=charged("electric_goggles",10000);p.setItemSlot(EquipmentSlot.HEAD,electric);p.setHealth(20);p.invulnerableTime=0;p.hurt(p.damageSources().mobAttack(new net.minecraft.world.entity.monster.Zombie(l)),10);double incoming=switch(l.getDifficulty()){case PEACEFUL->0;case EASY->6;case NORMAL->10;case HARD->15;};double absorbed=incoming*.165;check("IC2 electric armor absorbs EMT goggles damage",Math.abs(p.getHealth()-(20-incoming+absorbed))<.001&&ElectricItem.manager.getCharge(electric)==10000-Math.max(1,Math.round(absorbed))*100,p.getHealth()+" / "+ElectricItem.manager.getCharge(electric));
  boolean enchanting=EMTConfig.ENCHANTING.get();try{EMTConfig.ENCHANTING.set(false);check("electric armor enchantability disabled by default",!electric.isEnchantable()&&!chest.isEnchantable(),"disabled");EMTConfig.ENCHANTING.set(true);check("config enables goggles and infused chest enchanting",electric.isEnchantable()&&chest.isEnchantable()&&electric.getEnchantmentValue()==4&&chest.getEnchantmentValue()==4,"enabled");var armorTag=net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM,net.minecraft.resources.ResourceLocation.withDefaultNamespace("enchantable/armor"));check("native armor enchantments accept all twelve variants",EMTItems.ARMOR.values().stream().allMatch(item->new ItemStack(item.get()).is(armorTag)),"armor tag");}finally{EMTConfig.ENCHANTING.set(enchanting);}
  var shieldPos=anchor.offset(40,0,60);l.setBlock(shieldPos,EMTBlocks.SHIELD.get().defaultBlockState(),3);var shield=EMTBlocks.SHIELD.get().defaultBlockState();check("shield has no mining or silk drops",Block.getDrops(shield,l,shieldPos,null,p,new ItemStack(Items.DIAMOND_PICKAXE)).isEmpty(),"no drops");check("shield rejects entity destruction",!shield.getBlock().canEntityDestroy(shield,l,shieldPos,p),"protected");l.explode(null,shieldPos.getX()+.5,shieldPos.getY()+.5,shieldPos.getZ()+.5,1.5f,Level.ExplosionInteraction.BLOCK);check("shield survives actual explosion",l.getBlockState(shieldPos).is(EMTBlocks.SHIELD.get()),"blast resistant");clear(p);
 }
 public static void night(ServerLevel l,BlockPos anchor){var p=FakePlayerFactory.getMinecraft(l);clear(p);p.setPos(anchor.getX()+.5,anchor.getY()+3,anchor.getZ()+.5);var s=charged("solar_goggles",0);p.setItemSlot(EquipmentSlot.HEAD,s);tick(p,s);check("solar goggles original night output128EU",ElectricItem.manager.getCharge(s)==128,ElectricItem.manager.getCharge(s));clear(p);}
}
